// n8n Code Node — Server Health & Backup Report with Sizes
// Input: array of items from Merge node (each with stdout from client scripts)
// Output: Slack-formatted text message

const servers = [];

for (const item of items) {
  const out = item.json.stdout || "";
  if (!out.includes("SYSTEM REPORT")) continue;

  const server = {
    hostname: "-",
    cpu: "-",
    ram: "-",
    disk: "-",
    totalTables: "0",
    totalRows: "0",
    totalCols: "0",
    homeBackup: { status: "❌ Missing", size: "0B" },
    dbBackups: [],
  };

  // --- Extract hostname
  const nameMatch = out.match(/SYSTEM REPORT for (.*?) \(/);
  if (nameMatch) server.hostname = nameMatch[1].trim();

  // --- Extract CPU Load
  const cpuMatch = out.match(/CPU Load:\s*([\d\.]+\s+[\d\.]+\s+[\d\.]+)/);
  if (cpuMatch) server.cpu = cpuMatch[1].trim();

  // --- Extract Memory Usage
  const memMatch = out.match(/Memory:\s*([\d\/]+ MB used.*?)/);
  if (memMatch) server.ram = memMatch[1].trim();

  // --- Extract Disk Usage
  const diskMatch = out.match(/\/home usage:\s*(.*)/);
  if (diskMatch) server.disk = diskMatch[1].trim();

  // --- Extract Totals
  const totalsMatch = out.match(/📊 TOTALS ➜ Tables:\s*(\d+), Rows:\s*(\d+), Columns:\s*(\d+)/);
  if (totalsMatch) {
    server.totalTables = totalsMatch[1];
    server.totalRows = totalsMatch[2];
    server.totalCols = totalsMatch[3];
  }

  // --- Extract /home backup info
  const homeBackupMatch = out.match(/Home Backup:\s*(✅|❌)\s*\((.*?)\)/);
  if (homeBackupMatch) {
    server.homeBackup.status = homeBackupMatch[1].trim();
    server.homeBackup.size = homeBackupMatch[2].trim();
  } else {
    // fallback: detect manually if line like "/home_backup.tar.gz (2.4G)"
    const sizeLine = out.match(/\/home.*?\.tar\.gz.*?\((.*?)\)/);
    if (sizeLine) {
      server.homeBackup.status = "✅ Found";
      server.homeBackup.size = sizeLine[1].trim();
    }
  }

  // --- Extract DB backup info and size
  const dbLines = out.split("\n").filter(l => l.trim().startsWith("DB "));
  for (const line of dbLines) {
    const dbMatch = line.match(/DB\s+([^:]+):\s*(✅|⚠️|❌).*?\((.*?)\)/);
    if (dbMatch) {
      const dbName = dbMatch[1].trim();
      const status = dbMatch[2].trim();
      const size = dbMatch[3]?.trim() || "Unknown";
      server.dbBackups.push({ dbName, status, size });
    } else {
      // fallback if no size found
      const dbSimple = line.match(/DB\s+([^:]+):\s*(✅|⚠️|❌)/);
      if (dbSimple) {
        server.dbBackups.push({
          dbName: dbSimple[1].trim(),
          status: dbSimple[2].trim(),
          size: "Unknown",
        });
      }
    }
  }

  servers.push(server);
}

// --- Build Slack Report ---
let report = `*📊 YouStable Server Health & Backup Report — ${new Date().toISOString().slice(0, 10)}*\n\n`;

for (const s of servers) {
  report += `*🖥️ ${s.hostname}*\n`;
  report += `• *CPU Load:* ${s.cpu}\n`;
  report += `• *Memory:* ${s.ram}\n`;
  report += `• *Disk Usage:* ${s.disk}\n`;
  report += `• *Tables:* ${s.totalTables} | *Rows:* ${s.totalRows} | *Columns:* ${s.totalCols}\n\n`;

  report += `• *Home Backup:* ${s.homeBackup.status} (${s.homeBackup.size})\n`;

  if (s.dbBackups.length > 0) {
    report += `• *Database Backups:*\n`;
    s.dbBackups.forEach(db => {
      report += `   └ ${db.dbName}: ${db.status} (${db.size})\n`;
    });
  } else {
    report += `• *Database Backups:* ❌ None found\n`;
  }

  report += `\n──────────────────────────────\n\n`;
}

// Output for Slack
return [
  {
    json: {
      text: report
    }
  }
];
